import java.awt.image.BufferedImage
import java.io.{ByteArrayInputStream, ByteArrayOutputStream}
import java.util.concurrent.{ConcurrentHashMap, CountDownLatch, TimeUnit}
import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference}
import javax.imageio.ImageIO
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future}

sealed trait ImageOp
case class Resize(width: Int, height: Int) extends ImageOp
case class Rotate(degrees: Double) extends ImageOp
case class Composite(layerId: String, alpha: Float) extends ImageOp
case class MetadataTag(key: String, value: Any) extends ImageOp

sealed trait PipelineState
case object Running extends PipelineState
case object Draining extends PipelineState
case object Stopped extends PipelineState

class ImagePipeline(implicit ec: ExecutionContext) {
  private val state = new AtomicReference[PipelineState](Running)
  private val shutdownLatch = new CountDownLatch(1)
  private val operationRegistry = new ConcurrentHashMap[String, ImageOp]()
  private val layerCache = new ConcurrentHashMap[String, BufferedImage]()
  private val pendingOps = new java.util.concurrent.LinkedBlockingQueue[() => Unit]()

  def registerOperation(id: String, op: ImageOp): Boolean = {
    if (state.get() == Stopped) return false
    operationRegistry.put(id, op)
    true
  }

  def cacheLayer(layerId: String, data: BufferedImage): Unit = {
    layerCache.put(layerId, data)
  }

  def processImage(imageData: Array[Byte], ops: Seq[String]): Either[String, Array[Byte]] = {
    if (state.get() == Stopped) return Left("Pipeline stopped")

    try {
      var currentImage: BufferedImage = ImageIO.read(new ByteArrayInputStream(imageData))
      if (currentImage == null) return Left("Invalid image data")

      for (opId <- ops) {
        val op = operationRegistry.get(opId)
        if (op == null) return Left(s"Unknown operation: $opId")

        currentImage = applyOperation(currentImage, op)
      }

      Right(encodeImage(currentImage))
    } catch {
      case e: Exception => Left(s"Processing error: ${e.getMessage}")
    }
  }

  private def applyOperation(input: BufferedImage, op: ImageOp): BufferedImage = {
    op match {
      case Resize(w, h) =>
        val resized = new BufferedImage(
          Math.max(1, Math.min(w, 4096)),
          Math.max(1, Math.min(h, 4096)),
          input.getType)
        val g = resized.createGraphics()
        g.drawImage(input, 0, 0, resized.getWidth, resized.getHeight, null)
        g.dispose()
        resized

      case Rotate(degrees) =>
        val radians = Math.toRadians(degrees)
        val cos = Math.abs(Math.cos(radians))
        val sin = Math.abs(Math.sin(radians))
        val newW = (input.getWidth * cos + input.getHeight * sin).toInt
        val newH = (input.getWidth * sin + input.getHeight * cos).toInt
        val rotated = new BufferedImage(newW, newH, input.getType)
        val g = rotated.createGraphics()
        g.rotate(radians, newW / 2.0, newH / 2.0)
        g.drawImage(input, (newW - input.getWidth) / 2, (newH - input.getHeight) / 2, null)
        g.dispose()
        rotated

      case Composite(layerId, alpha) =>
        val layer = layerCache.get(layerId)
        if (layer == null) return input
        val clampedAlpha = Math.max(0.0f, Math.min(1.0f, alpha))
        val g = input.createGraphics()
        g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, clampedAlpha))
        g.drawImage(layer, 0, 0, null)
        g.dispose()
        input

      case MetadataTag(_, _) =>
        // Metadata operations are no-ops on the image itself;
        // metadata is handled separately in the serialization layer
        input
    }
  }

  def initiateShutdown(drainTimeoutMs: Long): Future[Boolean] = Future {
    state.set(Draining)

    // Process remaining operations
    val deadline = System.currentTimeMillis() + drainTimeoutMs
    while (!pendingOps.isEmpty && System.currentTimeMillis() < deadline) {
      val op = pendingOps.poll(100, TimeUnit.MILLISECONDS)
      if (op != null) op()
    }

    state.set(Stopped)
    shutdownLatch.countDown()
    pendingOps.isEmpty
  }

  def awaitShutdown(timeoutMs: Long): Boolean = {
    shutdownLatch.await(timeoutMs, TimeUnit.MILLISECONDS)
  }

  private def encodeImage(img: BufferedImage): Array[Byte] = {
    val baos = new ByteArrayOutputStream()
    ImageIO.write(img, "png", baos)
    baos.toByteArray
  }

  def getState: PipelineState = state.get()
}

object ImagePipelineApp {
  implicit val ec: ExecutionContext = ExecutionContext.global

  def main(args: Array[String]): Unit = {
    val pipeline = new ImagePipeline()

    // Register standard operations
    pipeline.registerOperation("thumb", Resize(128, 128))
    pipeline.registerOperation("rotate90", Rotate(90.0))
    pipeline.registerOperation("watermark", Composite("wm_layer", 0.3f))
    pipeline.registerOperation("tag_author", MetadataTag("author", "system"))

    // Graceful shutdown hook
    Runtime.getRuntime.addShutdownHook(new Thread(() => {
      pipeline.initiateShutdown(5000)
      pipeline.awaitShutdown(10000)
    }))
  }
}
